mapper.select:
SELECT DISTINCT u.id_ AS userId, u.name_ch AS userName
FROM sys_flow_user fu
INNER JOIN sys_user u ON fu.user_id = u.id_ AND u.is_valid = '1'
INNER JOIN sys_org o ON u.org_id = o.id_
WHERE fu.is_valid = 1
  AND fu.process_key = #{processKey}
  AND fu.task_def_key = #{taskDefKey}
  AND o.area_id IN

    #{areaId}

ORDER BY u.id_
